"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["56036"],{20379(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.geo.importacao.pacote_invalido","status":422,"titulo":"O pacote enviado n\xe3o \xe9 v\xe1lido"},"descricao":{"codigo":"uniplus.geo.importacao.pacote_invalido","requisitos":["UNI-REQ-0525","UNI-REQ-0533"],"oQueAconteceu":["O arquivo enviado n\xe3o \xe9 um pacote v\xe1lido da base dos Correios. O Geo confere a lista de arquivos do zip no ato do envio, sem descompactar, e responde **422**. A mensagem \xe9 sempre de texto fixo: nunca traz nome nem conte\xfado do arquivo enviado, s\xf3 contagens, os nomes das 15 tabelas e vers\xf5es de seis d\xedgitos.","A confer\xeancia tem duas etapas. Na primeira, a primeira falta encontrada interrompe a confer\xeancia e \xe9 a \xfanica respondida: arquivo que n\xe3o \xe9 um zip v\xe1lido; formato zip64, que n\xe3o \xe9 aceito; mais entradas que o limite configurado (o padr\xe3o \xe9 32); diret\xf3rio do zip acima de 64 KiB; diret\xf3rio do zip inconsistente com o tamanho do arquivo.","Passando a primeira etapa, todas as faltas do conte\xfado voltam juntas, na mesma resposta: tabela ausente ou repetida; arquivo `.sql` que n\xe3o \xe9 uma das 15 tabelas; nome de entrada inv\xe1lido (mais de 128 caracteres, fora do padr\xe3o pasta/arquivo, ou entrada de pasta repetida ou com conte\xfado); entradas em pastas diferentes; entrada cifrada; arquivo que acompanha o pacote, como uma imagem, acima de 5 MiB; entrada acima de 768 MiB ou conjunto acima de 1 GiB; tabelas de vers\xf5es diferentes; vers\xe3o com m\xeas fora de 01 a 12, que s\xf3 \xe9 conferida quando todas as tabelas t\xeam a mesma vers\xe3o.","O pacote vale quando tem exatamente as 15 tabelas, cada uma uma vez, todas no topo do zip ou todas na mesma pasta, e uma \xfanica vers\xe3o AAAAMM v\xe1lida, lida do nome dos arquivos de tabela e n\xe3o do nome do zip. Os arquivos que acompanham o pacote s\xe3o aceitos e ignorados."],"comoResolver":["Leia a mensagem do erro: ela diz o que n\xe3o confere. Gere o pacote de novo a partir da base dos Correios, com as 15 tabelas, cada uma uma vez, todas de uma s\xf3 vers\xe3o, e envie outra vez. Reenviar o mesmo arquivo d\xe1 o mesmo resultado.","Esta confer\xeancia n\xe3o olha o conte\xfado dos arquivos de tabela. Um defeito nele s\xf3 aparece depois da resposta de aceite (202), na carga em segundo plano: a execu\xe7\xe3o termina com falha, indicando a tabela e a linha, e a base publicada continua na vers\xe3o anterior. Acompanhe a execu\xe7\xe3o pelo endere\xe7o que a resposta de aceite devolveu."],"ondeAparece":["Envio do pacote (`POST /api/admin/geo/importacoes`), quando o arquivo n\xe3o \xe9 um zip v\xe1lido ou o conte\xfado do zip n\xe3o confere com o pacote esperado"]},"modulo":{"id":"geo","nome":"Geo","assunto":"Importacao"},"origem":{"repositorio":"unifesspa-edu-br/unifesspa-geo-api","commit":"241f54e88e265e24d3723798ba867fe69845ab0c"}}')}}]);